  useEffect(() => {
    if (!hqImage) {
      return;
    }

    const previousBodyOverflow = document.body.style.overflow;
    const previousHtmlOverflow = document.documentElement.style.overflow;

    document.body.style.overflow = "hidden";
    document.documentElement.style.overflow = "hidden";

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        setHqImage(null);
        setShareError(null);
        setHqZoom(1);
        return;
      }

      if (!(event.ctrlKey || event.metaKey)) {
        return;
      }

      if (event.key === "+" || event.key === "=") {
        event.preventDefault();
        setHqZoom((current) => Math.min(3, current + 0.25));
        return;
      }

      if (event.key === "-" || event.key === "_") {
        event.preventDefault();
        setHqZoom((current) => Math.max(0.5, current - 0.25));
        return;
      }

      if (event.key === "0") {
        event.preventDefault();
        setHqZoom(1);
      }
    }

    function handleWheel(event: WheelEvent) {
      if (!(event.ctrlKey || event.metaKey)) {
        return;
      }

      event.preventDefault();

      setHqZoom((current) => {
        const nextZoom =
          event.deltaY < 0
            ? current + 0.25
            : current - 0.25;

        return Math.min(3, Math.max(0.5, nextZoom));
      });
    }

    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("wheel", handleWheel, { passive: false });

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("wheel", handleWheel);
      document.body.style.overflow = previousBodyOverflow;
      document.documentElement.style.overflow = previousHtmlOverflow;
    };
  }, [hqImage]);

  useEffect(() => {
    if (!showMetadataModal) return;

    function handleMetadataEscape(event: KeyboardEvent) {
      if (event.key === "Escape") {
        event.stopImmediatePropagation();
        setShowMetadataModal(false);
      }
    }

    window.addEventListener("keydown", handleMetadataEscape, true);
    return () => window.removeEventListener("keydown", handleMetadataEscape, true);
  }, [showMetadataModal]);

  function handleScrollHqVertical(direction: "up" | "down") {
    const viewport = hqViewportRef.current;

    if (!viewport) {
      return;
    }

    const distance = Math.max(180, viewport.clientHeight * 0.55);

    viewport.scrollBy({
      top: direction === "down" ? distance : -distance,
      behavior: "smooth"
    });
  }

  function handleSpeakExample(text: string, index: number) {
    const exampleText = text.trim();

    if (!exampleText) {
      setSpeechError("Não há texto para reproduzir.");
      return;
    }

    if (!("speechSynthesis" in window)) {
      setSpeechError(
        "O recurso de voz não está disponível neste navegador."
      );
      return;
    }

    window.speechSynthesis.cancel();
    setSpeechError(null);
    setSpeakingExampleIndex(null);

    const utterance = new SpeechSynthesisUtterance(exampleText);
    const voices = window.speechSynthesis.getVoices();
    const selectedVoice = voices.find(
      (voice) => voice.lang.toLowerCase() === language.toLowerCase()
    ) ?? voices.find(
      (voice) => voice.lang.toLowerCase().split("-")[0] === language.split("-")[0]
    );

    if (selectedVoice) {
      utterance.voice = selectedVoice;
    }

    utterance.lang = language;
    utterance.rate = 0.9;
    utterance.pitch = 1;

    utterance.onstart = () => {
      setSpeakingExampleIndex(index);
    };

    utterance.onend = () => {
      setSpeakingExampleIndex(null);
    };

    utterance.onerror = () => {
      setSpeakingExampleIndex(null);
      setSpeechError("Não foi possível reproduzir o exemplo.");
    };

    window.speechSynthesis.speak(utterance);
  }

  async function handleCopyIntentionId() {
    if (!isAuthorMode() || !item?.id) return;

    try {
      // Mesmo fallback de cópia já utilizado neste componente.
      if (navigator.clipboard?.writeText) {
        try {
          await navigator.clipboard.writeText(item.id);
        } catch {
          copyIntentionIdFallback(item.id);
        }
      } else {
        copyIntentionIdFallback(item.id);
      }
      setCopiedIntentionId(item.id);
      setCopyIntentionIdError(null);
    } catch {
      setCopiedIntentionId(null);
      setCopyIntentionIdError("Não foi possível copiar o ID desta intenção.");
    }
  }

  function copyIntentionIdFallback(id: string) {
    const textarea = document.createElement("textarea");
    textarea.value = id;
    textarea.setAttribute("readonly", "");
    textarea.style.position = "fixed";
    textarea.style.opacity = "0";
    document.body.appendChild(textarea);
    try {
      textarea.focus();
      textarea.select();
      textarea.setSelectionRange(0, id.length);
      if (!document.execCommand("copy")) {
        throw new Error("Falha ao copiar ID.");
      }
    } finally {
      document.body.removeChild(textarea);
    }
  }

  async function handleCopySection(section: "pattern" | "examples") {
    if (!item) return;

    const content = section === "pattern"
      ? item.pattern ?? ""
      : (item.examples ?? [])
          .map((example) => `${example.pt}\r\n${targetSentence(example)}`)
          .join("\r\n\r\n");

    if (!content.trim()) return;

    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(content);
      } else {
        const textarea = document.createElement("textarea");
        textarea.value = content;
        textarea.setAttribute("readonly", "");
        textarea.style.position = "fixed";
        textarea.style.opacity = "0";
        textarea.style.pointerEvents = "none";
        document.body.appendChild(textarea);

        try {
          textarea.select();
          textarea.setSelectionRange(0, textarea.value.length);
          if (!document.execCommand("copy")) {
            throw new Error("Falha ao copiar o texto.");
          }
        } finally {
          document.body.removeChild(textarea);
        }
      }

      setCopySectionError(null);
      setCopiedSection(section);
      window.setTimeout(() => {
        setCopiedSection((current) => current === section ? null : current);
      }, 1500);
    } catch {
      setCopiedSection(null);
      setCopySectionError("Não foi possível copiar o conteúdo. Tente novamente.");
