import { useEffect, useState } from "react";

export function ScrollToTopButton() {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const mobile = window.matchMedia("(max-width: 768px)");
    const updateVisibility = () => {
      const next = mobile.matches && window.scrollY > 300;
      setVisible(previous => previous === next ? previous : next);
    };

    updateVisibility();
    window.addEventListener("scroll", updateVisibility, { passive: true });
    mobile.addEventListener("change", updateVisibility);
    return () => {
      window.removeEventListener("scroll", updateVisibility);
      mobile.removeEventListener("change", updateVisibility);
    };
  }, []);

  if (!visible) return null;

  return (
    <button type="button" className="scroll-to-top-button" aria-label="Ir para o topo" title="Ir para o topo"
      onClick={() => window.scrollTo({
        top: 0,
        behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "instant" : "smooth"
      })}>
      <svg aria-hidden="true" focusable="false" width="24" height="24" viewBox="0 0 24 24" fill="none"
        stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M12 19V5m-7 7 7-7 7 7" />
      </svg>
    </button>
  );
}

src/services/hashmapService.ts:
import { DEFAULT_SOURCE_LANGUAGE, DEFAULT_STUDENT_LANGUAGE, LANGUAGES, type SourceLanguage, type StudentLanguage } from "../config/languages";
import type {
  Example,
  HashmapData,
  HashmapDataV4,
  HashmapExampleV4,
  HashmapIntentionV4,
  MentalIntention
} from "../types/hashmap";
import { getHashmapCache, saveHashmapCache } from "./cacheService";



const LOCALE_HASHMAP_URLS: Record<string, string> = {
  "pt": LANGUAGES["pt-BR"].url,
  "pt-br": LANGUAGES["pt-BR"].url,
  "en": LANGUAGES["en-US"].url,
  "en-us": LANGUAGES["en-US"].url,
  "en-gb": LANGUAGES["en-US"].url,
  "es": LANGUAGES["es-ES"].url,
  "es-es": LANGUAGES["es-ES"].url,
  "es-mx": LANGUAGES["es-ES"].url,
  "fr": LANGUAGES["fr-FR"].url,
  "fr-fr": LANGUAGES["fr-FR"].url,
  "fr-ca": LANGUAGES["fr-FR"].url
};

export function resolveHashmapUrl(locale?: string | null): string {
  const configuredUrl = import.meta.env.VITE_HASHMAP_URL;
  const resolvedLocale = (locale ?? (typeof navigator !== "undefined" ? navigator.language : "") ?? "")
    .trim()
    .toLowerCase()
    .replace(/_/g, "-");
  const url = LOCALE_HASHMAP_URLS[resolvedLocale] ??
    LOCALE_HASHMAP_URLS[resolvedLocale.split("-")[0]] ??
    LANGUAGES[DEFAULT_STUDENT_LANGUAGE].url;

  if (configuredUrl?.includes("{language}")) {
    const fileLanguage = url.match(/sample-hashmap-(.+)\.json$/)?.[1] ?? DEFAULT_STUDENT_LANGUAGE;
    return configuredUrl.replaceAll("{language}", fileLanguage);
  }
  if (typeof configuredUrl === "string" && configuredUrl.trim() &&
      !configuredUrl.startsWith("/sample-hashmap")) {
    return configuredUrl.trim();
  }
  return url;
}

function getHashmapUrl(language: StudentLanguage): string {
  const configured = import.meta.env.VITE_HASHMAP_URL;
  if (configured?.includes("{language}")) {
    return configured.replaceAll("{language}", language);
  }
  if (language === DEFAULT_STUDENT_LANGUAGE && configured &&
      !configured.startsWith("/sample-hashmap")) {
    return configured;
  }
  return LANGUAGES[language].url;
}

function isObject(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function isExampleV4(value: unknown): value is HashmapExampleV4 {
  return isObject(value) && typeof value.id === "string" &&
    typeof value.exampleItem === "string" && typeof value.intent === "string";
}

function isIntentionV4(value: unknown): value is HashmapIntentionV4 {
  return isObject(value) && typeof value.id === "string" &&
    typeof value.intention === "string" &&
    (value.examples === undefined ||
      (Array.isArray(value.examples) && value.examples.every(isExampleV4)));
}

function validateHashmapV4(value: unknown, language: string): HashmapDataV4 {
  if (!isObject(value) || !isObject(value.metadata) || !Array.isArray(value.mentalMap)) {
    throw new Error(`Invalid JSON (${language}): metadata or mentalMap not found.`);
  }
  if (value.metadata.schemaVersion !== "4.0.0" || value.metadata.language !== language) {
    throw new Error(`Invalid JSON (${language}): schemaVersion or metadata.language mismatch.`);
  }
  if (!value.mentalMap.length || !value.mentalMap.every(isIntentionV4)) {
    throw new Error(`Invalid JSON (${language}): invalid mental intentions or examples.`);
  }
  return value as unknown as HashmapDataV4;
}

async function fetchCatalog(language: StudentLanguage): Promise<HashmapDataV4> {
  const response = await fetch(getHashmapUrl(language), { cache: "no-store" });
  if (!response.ok) {
    throw new Error(`Could not load Mental Hashmap (${language}). HTTP ${response.status}`);
  }
  return validateHashmapV4(await response.json(), language);
}

/**
 * No contrato JSON 4.0, `intention` ainda é o identificador textual em pt-BR
 * em TODOS os catálogos. O rótulo localizado está em `structure` nos catálogos
 * en-US, es-ES e fr-FR. Não usar `intention` como título desses idiomas.
 *
 * Quando o JSON passar a fornecer um campo `intention` traduzido, este
 * adaptador poderá ser revisado sem alterar os componentes da listagem.
 */
function localizedIntention(item: HashmapIntentionV4, locale: string): string {
  if (locale === "pt-BR") return item.intention;
  return item.structure?.trim() || item.pattern?.trim() || item.intention;
}

/**
 * O JSON 4.0 guarda uma frase por idioma. As telas atuais usam pares pt/en;
 * por isso associamos exemplos SOMENTE pelo UUID, nunca pela posição no array.
 * Exemplos sem correspondência entre origem e estudo permanecem nos JSONs.
 */
function normalizeHashmap(target: HashmapDataV4, source: HashmapDataV4): HashmapData {
  const sourceById = new Map(source.mentalMap.map((item) => [item.id, item]));

  const mentalMap: MentalIntention[] = target.mentalMap.map((item) => {
    const original = sourceById.get(item.id);
    const sourceExamples = new Map((original?.examples ?? []).map((example) => [example.id, example]));

    const examples: Example[] = (item.examples ?? []).flatMap((example) => {
      const pt = sourceExamples.get(example.id);
      if (!pt) return [];
      return [{
        ...example,
        pt: pt.exampleItem,
        en: example.exampleItem,
        ptIntent: pt.intent,
        enIntent: example.intent,
        // HQ pertence exclusivamente ao idioma de estudo (Target).
        // Não reutilizar a HQ do Source quando o Target não tiver imagem.
        hqImage: example.hqImage?.trim() || undefined
      }];
    });

    return {
      ...item,
      // Títulos visíveis sempre no par escolhido; não repetir o pt-BR fixo.
      intention: localizedIntention(original ?? item, source.metadata.language),
      english: item.structure || item.pattern || item.intention,
      targetIntention: localizedIntention(item, target.metadata.language),
      // Não perder os campos de busca da origem ao normalizar o catálogo de estudo.
      sourcePattern: original?.pattern,
      sourceStructure: original?.structure,
      sourceSearchTerms: original?.searchTerms ?? [],
      sourceCategory: original?.category,
      sourceTags: Array.from(new Set(original?.tags ?? [])),
      targetTags: Array.from(new Set(item.tags ?? [])),
      tags: Array.from(new Set([...(original?.tags ?? []), ...(item.tags ?? [])])),
      englishLevel: item.level ?? original?.level,
      examples
    };
  });

  return { metadata: { ...target.metadata, sourceLanguage: source.metadata.language }, mentalMap };
}

function isCachedHashmapV4(value: unknown, language: StudentLanguage, source: SourceLanguage): value is HashmapData {
  if (!isObject(value) || !isObject(value.metadata) ||
      value.metadata.schemaVersion !== "4.0.0" || value.metadata.language !== language ||
      value.metadata.sourceLanguage !== source ||
      !Array.isArray(value.mentalMap) || !value.mentalMap.length) return false;

  return value.mentalMap.every((item: unknown) =>
    isObject(item) && typeof item.id === "string" &&
    typeof item.intention === "string" && typeof item.english === "string" &&
    Array.isArray(item.sourceTags) && item.sourceTags.every((tag: unknown) => typeof tag === "string") &&
    Array.isArray(item.targetTags) && item.targetTags.every((tag: unknown) => typeof tag === "string") &&
    Array.isArray(item.examples) && item.examples.every((example: unknown) =>
      isExampleV4(example) && typeof (example as unknown as Record<string, unknown>).pt === "string" &&
      typeof (example as unknown as Record<string, unknown>).en === "string")
  );
}

export async function fetchHashmap(language: StudentLanguage = DEFAULT_STUDENT_LANGUAGE, source: SourceLanguage = DEFAULT_SOURCE_LANGUAGE): Promise<HashmapData> {
  if (language === source) throw new Error("Idioma de origem e idioma de estudo devem ser diferentes.");
  const [targetCatalog, sourceCatalog] = await Promise.all([
    fetchCatalog(language),
    fetchCatalog(source)
  ]);
  const normalized = normalizeHashmap(targetCatalog, sourceCatalog);
  saveHashmapCache(normalized, language, source);
  return normalized;
}

export async function loadHashmap(language: StudentLanguage = DEFAULT_STUDENT_LANGUAGE, source: SourceLanguage = DEFAULT_SOURCE_LANGUAGE): Promise<{
  data: HashmapData;
  source: "remote" | "cache";
}> {
  try {
    const data = await fetchHashmap(language, source);
    return { data, source: "remote" };
  } catch (remoteError) {
    const cached = getHashmapCache(language, source);
    if (isCachedHashmapV4(cached, language, source)) {
      return { data: cached, source: "cache" };
    }
    throw remoteError;
  }
}

src/components/BasicTraining.tsx:
import { isAuthorMode } from "../utils/authorMode";
import { LANGUAGES, type SourceLanguage, type StudentLanguage } from "../config/languages";
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { MentalIntention } from "../types/hashmap";
import {
  evaluateTrainingWithAI,
  type AIEvaluationResult
} from "../services/aiEvaluationService";
import { translateBetweenLanguages } from "../services/googleTranslateService";
import { validateIntention } from "../services/intentionValidator";

const AI_ENABLED = import.meta.env.VITE_AI_ENABLED === "true";

interface SpeechRecognitionResultEventLike extends Event {
  resultIndex: number;
  results: ArrayLike<{
    0: {
      transcript: string;
    };
    isFinal: boolean;
  }>;
}

interface SpeechRecognitionErrorEventLike extends Event {
  error: string;
}

interface SpeechRecognitionLike {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  maxAlternatives: number;
  onstart: (() => void) | null;
  onresult: ((event: SpeechRecognitionResultEventLike) => void) | null;
  onerror: ((event: SpeechRecognitionErrorEventLike) => void) | null;
  onend: (() => void) | null;
  start: () => void;
  stop: () => void;
  abort: () => void;
}

type SpeechRecognitionConstructor = new () => SpeechRecognitionLike;

function isMobileDevice(): boolean {
  const userAgent = navigator.userAgent;

  const isPhoneOrTablet =
    /Android|iPhone|iPad|iPod|IEMobile|Opera Mini/i.test(userAgent);

  const isIPadOS =
    navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1;

  return isPhoneOrTablet || isIPadOS;
}

function getSpeechRecognitionConstructor(): SpeechRecognitionConstructor | null {
  const speechWindow = window as typeof window & {
    SpeechRecognition?: SpeechRecognitionConstructor;
    webkitSpeechRecognition?: SpeechRecognitionConstructor;
  };

  return (
    speechWindow.SpeechRecognition ??
    speechWindow.webkitSpeechRecognition ??
    null
  );
}


function renderHighlightedText(
  text: string,
  highlight?: string
) {
  if (!highlight) {
    return text;
  }

  const index = text.toLocaleLowerCase().indexOf(highlight.toLocaleLowerCase());

  if (index === -1) {
    return text;
  }

  const before = text.slice(0, index);
  const after = text.slice(index + highlight.length);

  return (
    <>
      {before}
      <strong className="intention-highlight">
        {text.slice(index, index + highlight.length)}
      </strong>
      {after}
    </>
  );
}

interface BasicTrainingProps {
  intention: MentalIntention;
  language: StudentLanguage;
  sourceLanguage: SourceLanguage;
  onBack: () => void;
}

interface VerbItem {
  id: string;
  base: string;
  type?: "regular" | "irregular";
  past?: string;
  pastParticiple?: string;
  thirdPerson?: string;
  gerund?: string;
  meanings?: string[];
  examples?: Array<{
    en: string;
    pt: string;
  }>;
}

interface NounItem {
  id: string;
  noun: string;
  meanings?: string[];
  examples?: Array<{
    en: string;
    pt: string;
  }>;
}

interface AdjectiveItem {
  id: string;
  adjective: string;
  meanings?: string[];
  examples?: Array<{
    en: string;
    pt: string;
  }>;
}

interface VerbData {
  verbs: VerbItem[];
}

interface NounData {
  nouns: NounItem[];
}

interface AdjectiveData {
  adjectives: AdjectiveItem[];
}

function pickRandom<T>(items: T[]): T | null {
  if (items.length === 0) {
    return null;
  }

  const randomIndex = Math.floor(Math.random() * items.length);
  return items[randomIndex];
}

export function BasicTraining({
  intention,
  language,
  sourceLanguage,
  onBack
}: BasicTrainingProps) {
  const languageName = LANGUAGES[language].name.toLowerCase();
  const sourceLanguageName = LANGUAGES[sourceLanguage].name.toLowerCase();
  // Os vocabulários são em inglês, com significados apenas em pt-BR.
  // Para outros pares, a prática usa os exemplos bilíngues do Hashmap.
  const hasEnglishVocabulary = language === "en-US" && sourceLanguage === "pt-BR";
  const [verbs, setVerbs] = useState<VerbItem[]>([]);
  const [nouns, setNouns] = useState<NounItem[]>([]);
  const [adjectives, setAdjectives] = useState<AdjectiveItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [round, setRound] = useState(0);
  const referenceExample = intention.examples?.length
    ? intention.examples[round % intention.examples.length]
    : undefined;
  const [studentText, setStudentText] = useState("");
  const intentionValidation = useMemo(
    () => validateIntention(studentText, intention, language),
    [studentText, intention, language]
  );
  const [evaluating, setEvaluating] = useState(false);
  const [evaluationError, setEvaluationError] = useState<string | null>(null);
  const [evaluation, setEvaluation] = useState<AIEvaluationResult | null>(null);
  const [translating, setTranslating] = useState(false);
  const [translationError, setTranslationError] = useState<string | null>(null);
  const [googleTranslation, setGoogleTranslation] = useState<string | null>(null);
  const [speaking, setSpeaking] = useState(false);
  const [speakingExample, setSpeakingExample] = useState<"source" | "target" | null>(null);
  const [evaluationSpeaking, setEvaluationSpeaking] = useState<
    "corrected" | "better" | null
  >(null);
  const [speechError, setSpeechError] = useState<string | null>(null);
  const [evaluationCopyStatus, setEvaluationCopyStatus] = useState<{
    target: "corrected" | "better";
    status: "copied" | "error";
  } | null>(null);
  const [copyStatus, setCopyStatus] = useState<"idle" | "copied" | "error">("idle");
  const [dictating, setDictating] = useState(false);
  const showDictationButton = !isMobileDevice();
  const [dictationError, setDictationError] = useState<string | null>(null);
  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
  const trainingGridRef = useRef<HTMLDivElement>(null);

  const googleTranslationCardRef = useRef<HTMLElement | null>(null);
  const aiEvaluationCardRef = useRef<HTMLElement | null>(null);

  // O resultado precisa estar montado no DOM antes de posicionar a tela.
  useLayoutEffect(() => {
    if (googleTranslation) {
      googleTranslationCardRef.current?.scrollIntoView({ behavior: "auto", block: "start" });
    }
  }, [googleTranslation]);

  useLayoutEffect(() => {
    if (evaluation && AI_ENABLED) {
      aiEvaluationCardRef.current?.scrollIntoView({ behavior: "auto", block: "start" });
    }
  }, [evaluation]);

  useEffect(() => {
    let active = true;

    async function loadVocabulary() {
      setLoading(true);
      setError(null);
      if (!hasEnglishVocabulary) {
        setVerbs([]);
        setNouns([]);
        setAdjectives([]);
        setLoading(false);
        return;
      }

      try {
        const [verbsResponse, nounsResponse, adjectivesResponse] =
          await Promise.all([
            fetch("/english-verbs-common.json"),
            fetch("/english-nouns-common.json"),
            fetch("/english-adjectives-common.json")
          ]);

        if (
          !verbsResponse.ok ||
          !nounsResponse.ok ||
          !adjectivesResponse.ok
        ) {
          throw new Error(
            "Não foi possível carregar os arquivos de vocabulário."
          );
        }

        const verbsData = (await verbsResponse.json()) as VerbData;
        const nounsData = (await nounsResponse.json()) as NounData;
        const adjectivesData =
          (await adjectivesResponse.json()) as AdjectiveData;

        if (!active) {
          return;
        }

        setVerbs(verbsData.verbs ?? []);
        setNouns(nounsData.nouns ?? []);
        setAdjectives(adjectivesData.adjectives ?? []);
      } catch (err) {
        if (!active) {
          return;
        }

        setError(
          err instanceof Error
            ? err.message
            : "Erro inesperado ao carregar o vocabulário."
        );
      } finally {
        if (active) {
          setLoading(false);
        }
      }
    }

    loadVocabulary();

    return () => {
      active = false;
    };
  }, [hasEnglishVocabulary]);

  useEffect(() => {
    return () => {
      recognitionRef.current?.abort();

      if ("speechSynthesis" in window) {
        window.speechSynthesis.cancel();
      }
    };
  }, []);

  const trainingItems = useMemo(() => {
    return {
      verb: pickRandom(verbs),
      noun: pickRandom(nouns),
      adjective: pickRandom(adjectives)
    };
  }, [verbs, nouns, adjectives, round]);

  function generateNewRound() {
    setRound((current) => current + 1);
    setStudentText("");
    setEvaluation(null);
    setEvaluationCopyStatus(null);
    setEvaluationError(null);
    setGoogleTranslation(null);
    setTranslationError(null);
    setSpeechError(null);
    setSpeaking(false);
    setSpeakingExample(null);
    setEvaluationSpeaking(null);
    setCopyStatus("idle");
    setDictationError(null);
    recognitionRef.current?.abort();
    recognitionRef.current = null;
    setDictating(false);

    if ("speechSynthesis" in window) {
      window.speechSynthesis.cancel();
    }

    // Após um novo sorteio, reposiciona o estudo no início dos cartões sorteados apenas no celular.
    if (window.matchMedia("(max-width: 820px)").matches) {
      window.requestAnimationFrame(() => {
        trainingGridRef.current?.scrollIntoView({
          behavior: "smooth",
          block: "start"
        });
      });
    }
  }

  function handleSpeakReferenceExample(text: string, locale: StudentLanguage, side: "source" | "target") {
    if (!("speechSynthesis" in window)) {
      setSpeechError("O recurso de voz não está disponível neste navegador.");
      return;
    }
    window.speechSynthesis.cancel();
    setSpeechError(null);
    setSpeaking(false);
    setEvaluationSpeaking(null);
    setSpeakingExample(null);

    const utterance = new SpeechSynthesisUtterance(text);
    const voices = window.speechSynthesis.getVoices();
    utterance.voice = voices.find((voice) => voice.lang.toLowerCase() === locale.toLowerCase())
      ?? voices.find((voice) => voice.lang.toLowerCase().split("-")[0] === locale.split("-")[0])
      ?? null;
    utterance.lang = locale;
    utterance.rate = 0.9;
    utterance.onstart = () => setSpeakingExample(side);
    utterance.onend = () => setSpeakingExample(null);
    utterance.onerror = (event) => {
      setSpeakingExample(null);
      if (event.error !== "interrupted" && event.error !== "canceled") {
        setSpeechError(`Não foi possível reproduzir o exemplo em ${LANGUAGES[locale].name.toLowerCase()}.`);
      }
    };
    window.speechSynthesis.speak(utterance);
  }

  function handleToggleDictation() {
    if (dictating) {
      recognitionRef.current?.stop();
      return;
    }

    const SpeechRecognitionApi = getSpeechRecognitionConstructor();

    if (!SpeechRecognitionApi) {
      setDictationError(
        "O ditado por voz não está disponível neste navegador. Use Chrome ou Edge no computador."
      );
      return;
    }

    setDictationError(null);

    const recognition = new SpeechRecognitionApi();
    recognition.lang = language;
    recognition.continuous = true;
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => {
      setDictating(true);
    };

    recognition.onresult = (event) => {
      const transcripts: string[] = [];

      for (
        let index = event.resultIndex;
        index < event.results.length;
        index += 1
      ) {
        const result = event.results[index];

        if (result.isFinal && result[0]?.transcript) {
          transcripts.push(result[0].transcript.trim());
        }
      }

      const transcript = transcripts.join(" ").trim();

      if (!transcript) {
        return;
      }

      setStudentText((current) => {
        const currentText = current.trimEnd();

        return currentText
          ? `${currentText} ${transcript}`
          : transcript;
      });

      setCopyStatus("idle");
      setEvaluation(null);
    setEvaluationCopyStatus(null);
      setEvaluationError(null);
      setGoogleTranslation(null);
      setTranslationError(null);
      setSpeechError(null);
    };

    recognition.onerror = (event) => {
      if (event.error === "aborted") {
        return;
      }

      if (event.error === "not-allowed" || event.error === "service-not-allowed") {
        setDictationError(
          "Permita o acesso ao microfone no navegador para usar o ditado."
        );
        return;
      }

      if (event.error === "no-speech") {
        setDictationError(
          "Nenhuma fala foi detectada. Clique no microfone e tente novamente."
        );
        return;
      }

      setDictationError("Não foi possível reconhecer sua fala. Tente novamente.");
    };

    recognition.onend = () => {
      recognitionRef.current = null;
      setDictating(false);
    };

    recognitionRef.current = recognition;

    try {
      recognition.start();
    } catch {
      recognitionRef.current = null;
      setDictating(false);
      setDictationError("Não foi possível iniciar o microfone.");
    }
  }

  function handleClearStudentText() {
    setStudentText("");
    setCopyStatus("idle");
    setEvaluation(null);
    setEvaluationCopyStatus(null);
    setEvaluationError(null);
    setGoogleTranslation(null);
    setTranslationError(null);
    setSpeechError(null);
    setSpeaking(false);
    setSpeakingExample(null);
    setEvaluationSpeaking(null);
    setDictationError(null);
    recognitionRef.current?.abort();
    recognitionRef.current = null;
    setDictating(false);

    if ("speechSynthesis" in window) {
      window.speechSynthesis.cancel();
    }
  }

  async function handleCopyStudentText() {
    const textToCopy = studentText.trim();

    if (!textToCopy) {
      return;
    }

    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(textToCopy);
      } else {
        const textarea = document.createElement("textarea");
        textarea.value = textToCopy;
        textarea.setAttribute("readonly", "");
        textarea.style.position = "fixed";
        textarea.style.opacity = "0";
        textarea.style.pointerEvents = "none";
        document.body.appendChild(textarea);
        textarea.select();

        const copied = document.execCommand("copy");
        document.body.removeChild(textarea);

        if (!copied) {
          throw new Error("Não foi possível copiar a frase.");
        }
      }

      setCopyStatus("copied");
      window.setTimeout(() => {
        setCopyStatus("idle");
      }, 1500);
    } catch {
      setCopyStatus("error");
      window.setTimeout(() => {
        setCopyStatus("idle");
      }, 1500);
    }
  }

  function handleOpenGoogleTranslate() {
    const englishText = studentText.trim();

    if (!englishText) {
      return;
    }

    const googleTranslateUrl = new URL("https://translate.google.com/");
    googleTranslateUrl.searchParams.set("hl", sourceLanguage);
    googleTranslateUrl.searchParams.set("sl", language.split("-")[0]);
    googleTranslateUrl.searchParams.set("tl", sourceLanguage.split("-")[0]);
    googleTranslateUrl.searchParams.set("text", englishText);
    googleTranslateUrl.searchParams.set("op", "translate");

    window.open(
      googleTranslateUrl.toString(),
      "_blank",
      "noopener,noreferrer"
    );
  }

  function handleOpenEvaluationGoogleTranslate(text: string) {
