import { isAuthorMode } from "../utils/authorMode";
import { LANGUAGES, type StudentLanguage } from "../config/languages";
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { MentalIntention } from "../types/hashmap";
import {
  evaluateTrainingWithAI,
  type AIEvaluationResult
} from "../services/aiEvaluationService";
import { translateStudentLanguageToPortuguese } from "../services/googleTranslateService";
import { validateIntention } from "../services/intentionValidator";

const AI_ENABLED = import.meta.env.VITE_AI_ENABLED === "true";

interface SpeechRecognitionResultEventLike extends Event {
  resultIndex: number;
  results: ArrayLike<{
    0: {
      transcript: string;
    };
    isFinal: boolean;
  }>;
}

interface SpeechRecognitionErrorEventLike extends Event {
  error: string;
}

interface SpeechRecognitionLike {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  maxAlternatives: number;
  onstart: (() => void) | null;
  onresult: ((event: SpeechRecognitionResultEventLike) => void) | null;
  onerror: ((event: SpeechRecognitionErrorEventLike) => void) | null;
  onend: (() => void) | null;
  start: () => void;
  stop: () => void;
  abort: () => void;
}

type SpeechRecognitionConstructor = new () => SpeechRecognitionLike;

function isMobileDevice(): boolean {
  const userAgent = navigator.userAgent;

  const isPhoneOrTablet =
    /Android|iPhone|iPad|iPod|IEMobile|Opera Mini/i.test(userAgent);

  const isIPadOS =
    navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1;

  return isPhoneOrTablet || isIPadOS;
}

function getSpeechRecognitionConstructor(): SpeechRecognitionConstructor | null {
  const speechWindow = window as typeof window & {
    SpeechRecognition?: SpeechRecognitionConstructor;
    webkitSpeechRecognition?: SpeechRecognitionConstructor;
  };

  return (
    speechWindow.SpeechRecognition ??
    speechWindow.webkitSpeechRecognition ??
    null
  );
}


function renderHighlightedText(
  text: string,
  highlight?: string
) {
  if (!highlight) {
    return text;
  }

  const index = text.indexOf(highlight);

  if (index === -1) {
    return text;
  }

  const before = text.slice(0, index);
  const after = text.slice(index + highlight.length);

  return (
    <>
      {before}
      <strong className="intention-highlight">
        {highlight}
      </strong>
      {after}
    </>
  );
}

interface AdvancedTrainingProps {
  intention: MentalIntention;
  language: StudentLanguage;
  onBack: () => void;
}

interface VerbItem {
  id: string;
  base: string;
  type?: "regular" | "irregular";
  past?: string;
  pastParticiple?: string;
  thirdPerson?: string;
  gerund?: string;
  meanings?: string[];
}

interface NounItem {
  id: string;
  noun: string;
  meanings?: string[];
}

interface AdjectiveItem {
  id: string;
  adjective: string;
  meanings?: string[];
}

interface ConnectorItem {
  id: string;
  connector: string;
  meaning?: string;
  meanings?: string[];
  type?: string;
}

interface VerbData {
  verbs: VerbItem[];
}

interface NounData {
  nouns: NounItem[];
}

interface AdjectiveData {
  adjectives: AdjectiveItem[];
}

interface ConnectorData {
  connectors: ConnectorItem[];
}

function shuffle<T>(items: T[]): T[] {
  const result = [...items];

  for (let index = result.length - 1; index > 0; index -= 1) {
    const randomIndex = Math.floor(Math.random() * (index + 1));

    [result[index], result[randomIndex]] = [
      result[randomIndex],
      result[index]
    ];
  }

  return result;
}

function pickRandomItems<T>(items: T[], amount: number): T[] {
  return shuffle(items).slice(0, Math.min(amount, items.length));
}

function connectorMeaning(connector: ConnectorItem): string {
  if (connector.meanings && connector.meanings.length > 0) {
    return connector.meanings.join(" / ");
  }

  return connector.meaning ?? "";
}

/** Exibe o resultado da verificação local da intenção mental. */
function renderIntentionFeedback(validation: ReturnType<typeof validateIntention>) {
  if (validation.status === "empty") {
    return null;
  }

  return (
    <p
      role="status"
      aria-live="polite"
      style={{
        margin: "0.55rem 0 0",
        display: "inline-flex",
        alignItems: "center",
        maxWidth: "100%",
        boxSizing: "border-box",
        padding: "0.5rem 0.9rem",
        borderRadius: "999px",
        fontSize: "0.9rem",
        fontWeight: 600,
        lineHeight: 1.4,
        boxShadow: "0 2px 8px rgba(15, 23, 42, 0.06)",
        color:
          validation.status === "found"
            ? "#166534"
            : validation.status === "missing"
              ? "#92400e"
              : "#475569",
        backgroundColor:
          validation.status === "found"
            ? "#f0fdf4"
            : validation.status === "missing"
              ? "#fffbeb"
              : "#f1f5f9",
        border:
          validation.status === "found"
            ? "1px solid #bbf7d0"
            : validation.status === "missing"
              ? "1px solid #fde68a"
              : "1px solid #cbd5e1"
      }}
    >
      {validation.status === "found"
        ? "✓ Intenção mental identificada!"
        : validation.status === "missing"
          ? "⚠ Você ainda não utilizou a intenção mental."
          : "Validação automática indisponível para esta intenção."}
    </p>
  );
}

export function AdvancedTraining({
  intention,
  language,
  onBack
}: AdvancedTrainingProps) {
  const languageName = LANGUAGES[language].name.toLowerCase();
  const [verbs, setVerbs] = useState<VerbItem[]>([]);
  const [nouns, setNouns] = useState<NounItem[]>([]);
  const [adjectives, setAdjectives] = useState<AdjectiveItem[]>([]);
  const [connectors, setConnectors] = useState<ConnectorItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [round, setRound] = useState(0);
  const [sentenceOne, setSentenceOne] = useState("");
  const [sentenceTwo, setSentenceTwo] = useState("");
  const [combinedSentence, setCombinedSentence] = useState("");
  const combinedSentenceValidation = useMemo(
    () => validateIntention(combinedSentence, intention),
    [combinedSentence, intention]
  );
  const [evaluating, setEvaluating] = useState(false);
  const [evaluationError, setEvaluationError] = useState<string | null>(null);
  const [evaluation, setEvaluation] = useState<AIEvaluationResult | null>(null);
  const [translating, setTranslating] = useState(false);
  const [translationError, setTranslationError] = useState<string | null>(null);
  const [googleTranslation, setGoogleTranslation] = useState<string | null>(null);
  const [speaking, setSpeaking] = useState(false);
  const [evaluationSpeaking, setEvaluationSpeaking] = useState<
    "corrected" | "better" | null
  >(null);
  const [speechError, setSpeechError] = useState<string | null>(null);
  const [evaluationCopyStatus, setEvaluationCopyStatus] = useState<{
    target: "corrected" | "better";
    status: "copied" | "error";
  } | null>(null);
  const [copyStatus, setCopyStatus] = useState<"idle" | "copied" | "error">("idle");
  const [draftCopyStatus, setDraftCopyStatus] = useState<
    Record<"sentenceOne" | "sentenceTwo", "idle" | "copied" | "error">
  >({ sentenceOne: "idle", sentenceTwo: "idle" });
  const [dictating, setDictating] = useState(false);
  const [dictationTarget, setDictationTarget] = useState<
    "sentenceOne" | "sentenceTwo" | "combined" | null
  >(null);
  const showDictationButton = !isMobileDevice();
  const [dictationError, setDictationError] = useState<string | null>(null);
  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
  const trainingGridRef = useRef<HTMLDivElement | null>(null);

  const googleTranslationCardRef = useRef<HTMLElement | null>(null);
  const aiEvaluationCardRef = useRef<HTMLElement | null>(null);

  // O resultado precisa estar montado no DOM antes de posicionar a tela.
  useLayoutEffect(() => {
    if (googleTranslation) {
      googleTranslationCardRef.current?.scrollIntoView({ behavior: "auto", block: "start" });
    }
  }, [googleTranslation]);

  useLayoutEffect(() => {
    if (evaluation && AI_ENABLED) {
      aiEvaluationCardRef.current?.scrollIntoView({ behavior: "auto", block: "start" });
    }
  }, [evaluation]);

  useEffect(() => {
    let active = true;

    async function loadVocabulary() {
      setLoading(true);
      setError(null);

      try {
        const [
          verbsResponse,
          nounsResponse,
          adjectivesResponse,
          connectorsResponse
        ] = await Promise.all([
          fetch("/english-verbs-common.json"),
          fetch("/english-nouns-common.json"),
          fetch("/english-adjectives-common.json"),
          fetch("/english-connectors-common.json")
        ]);

        if (
          !verbsResponse.ok ||
          !nounsResponse.ok ||
          !adjectivesResponse.ok ||
          !connectorsResponse.ok
        ) {
          throw new Error(
            "Não foi possível carregar os arquivos de vocabulário."
          );
        }

        const verbsData = (await verbsResponse.json()) as VerbData;
        const nounsData = (await nounsResponse.json()) as NounData;
        const adjectivesData =
          (await adjectivesResponse.json()) as AdjectiveData;
        const connectorsData =
          (await connectorsResponse.json()) as ConnectorData;

        if (!active) {
          return;
        }

        setVerbs(verbsData.verbs ?? []);
        setNouns(nounsData.nouns ?? []);
        setAdjectives(adjectivesData.adjectives ?? []);
        setConnectors(connectorsData.connectors ?? []);
      } catch (err) {
        if (!active) {
          return;
        }

        setError(
          err instanceof Error
            ? err.message
            : "Erro inesperado ao carregar o vocabulário."
        );
      } finally {
        if (active) {
          setLoading(false);
        }
      }
    }

    loadVocabulary();

    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    return () => {
      recognitionRef.current?.abort();

      if ("speechSynthesis" in window) {
        window.speechSynthesis.cancel();
      }
    };
  }, []);

  const trainingItems = useMemo(() => {
    return {
      verbs: pickRandomItems(verbs, 2),
      adjectives: pickRandomItems(adjectives, 2),
      nouns: pickRandomItems(nouns, 2),
      connectors: pickRandomItems(connectors, 4)
    };
  }, [verbs, nouns, adjectives, connectors, round]);

  const hasEnoughVocabulary =
    trainingItems.verbs.length === 2 &&
    trainingItems.adjectives.length === 2 &&
    trainingItems.nouns.length === 2 &&
    trainingItems.connectors.length === 4;

  function generateNewRound() {
    setRound((current) => current + 1);
    setSentenceOne("");
    setSentenceTwo("");
    setCombinedSentence("");
    setEvaluation(null);
    setEvaluationCopyStatus(null);
    setEvaluationError(null);
    setGoogleTranslation(null);
    setTranslationError(null);
    setSpeechError(null);
    setSpeaking(false);
    setEvaluationSpeaking(null);
    setCopyStatus("idle");
    setDraftCopyStatus({ sentenceOne: "idle", sentenceTwo: "idle" });
    setDictationError(null);
    recognitionRef.current?.abort();
    recognitionRef.current = null;
    setDictating(false);
    setDictationTarget(null);

    if ("speechSynthesis" in window) {
      window.speechSynthesis.cancel();
    }

    window.requestAnimationFrame(() => {
      trainingGridRef.current?.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    });
  }

  function handleToggleDictation(
    target: "sentenceOne" | "sentenceTwo" | "combined"
  ) {
    if (dictating) {
      recognitionRef.current?.stop();
      return;
    }

    const SpeechRecognitionApi = getSpeechRecognitionConstructor();

    if (!SpeechRecognitionApi) {
      setDictationError(
        "O ditado por voz não está disponível neste navegador. Use Chrome ou Edge no computador."
      );
      return;
    }

    setDictationError(null);
    setDictationTarget(target);

    const recognition = new SpeechRecognitionApi();
    recognition.lang = language;
    recognition.continuous = true;
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => {
      setDictating(true);
    };

    recognition.onresult = (event) => {
      const transcripts: string[] = [];

      for (
        let index = event.resultIndex;
        index < event.results.length;
        index += 1
      ) {
        const result = event.results[index];

        if (result.isFinal && result[0]?.transcript) {
          transcripts.push(result[0].transcript.trim());
        }
      }

      const transcript = transcripts.join(" ").trim();

      if (!transcript) {
        return;
      }

      const appendTranscript = (current: string) => {
        const currentText = current.trimEnd();

        return currentText
          ? `${currentText} ${transcript}`
          : transcript;
      };

      if (target === "sentenceOne") {
        setSentenceOne(appendTranscript);
        setDraftCopyStatus((current) => ({ ...current, sentenceOne: "idle" }));
      } else if (target === "sentenceTwo") {
        setSentenceTwo(appendTranscript);
        setDraftCopyStatus((current) => ({ ...current, sentenceTwo: "idle" }));
      } else {
        setCombinedSentence(appendTranscript);
        setCopyStatus("idle");
        setGoogleTranslation(null);
        setTranslationError(null);
        setSpeechError(null);
      }

      setEvaluation(null);
    setEvaluationCopyStatus(null);
      setEvaluationError(null);
    };

    recognition.onerror = (event) => {
      if (event.error === "aborted") {
        return;
      }

      if (event.error === "not-allowed" || event.error === "service-not-allowed") {
        setDictationError(
          "Permita o acesso ao microfone no navegador para usar o ditado."
        );
        return;
      }

      if (event.error === "no-speech") {
        setDictationError(
          "Nenhuma fala foi detectada. Clique no microfone e tente novamente."
        );
        return;
      }

      setDictationError("Não foi possível reconhecer sua fala. Tente novamente.");
    };

    recognition.onend = () => {
      recognitionRef.current = null;
      setDictating(false);
      setDictationTarget(null);
    };

    recognitionRef.current = recognition;

    try {
      recognition.start();
    } catch {
      recognitionRef.current = null;
      setDictating(false);
      setDictationTarget(null);
      setDictationError("Não foi possível iniciar o microfone.");
    }
  }


  function handleClearSentence(target: "sentenceOne" | "sentenceTwo") {
    setDraftCopyStatus((current) => ({ ...current, [target]: "idle" }));
    if (target === "sentenceOne") {
      setSentenceOne("");
    } else {
      setSentenceTwo("");
    }

    setEvaluation(null);
    setEvaluationCopyStatus(null);
    setEvaluationError(null);
    setDictationError(null);

    if (dictating && dictationTarget === target) {
      recognitionRef.current?.abort();
      recognitionRef.current = null;
      setDictating(false);
      setDictationTarget(null);
    }
  }

  function handleClearStudentText() {
    setCombinedSentence("");
    setCopyStatus("idle");
    setEvaluation(null);
    setEvaluationCopyStatus(null);
    setEvaluationError(null);
    setGoogleTranslation(null);
    setTranslationError(null);
    setSpeechError(null);
    setSpeaking(false);
    setEvaluationSpeaking(null);
    setDictationError(null);
    recognitionRef.current?.abort();
    recognitionRef.current = null;
    setDictating(false);
    setDictationTarget(null);

    if ("speechSynthesis" in window) {
      window.speechSynthesis.cancel();
    }
  }

  async function handleCopyDraftSentence(target: "sentenceOne" | "sentenceTwo") {
    const textToCopy = (target === "sentenceOne" ? sentenceOne : sentenceTwo).trim();
    if (!textToCopy) return;

    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(textToCopy);
      } else {
        // Compatibilidade com navegadores que não disponibilizam Clipboard API.
        const textarea = document.createElement("textarea");
        textarea.value = textToCopy;
        textarea.setAttribute("readonly", "");
        textarea.style.position = "fixed";
        textarea.style.opacity = "0";
        textarea.style.pointerEvents = "none";
        document.body.appendChild(textarea);
        try {
          textarea.select();
          if (!document.execCommand("copy")) {
            throw new Error("Não foi possível copiar a frase.");
          }
        } finally {
          textarea.remove();
        }
      }
      setDraftCopyStatus((current) => ({ ...current, [target]: "copied" }));
    } catch {
      setDraftCopyStatus((current) => ({ ...current, [target]: "error" }));
    }
  }

  async function handleCopyStudentText() {
    const textToCopy = combinedSentence.trim();

    if (!textToCopy) {
      return;
    }

    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(textToCopy);
      } else {
        const textarea = document.createElement("textarea");
        textarea.value = textToCopy;
        textarea.setAttribute("readonly", "");
        textarea.style.position = "fixed";
        textarea.style.opacity = "0";
        textarea.style.pointerEvents = "none";
        document.body.appendChild(textarea);
        textarea.select();

        const copied = document.execCommand("copy");
        document.body.removeChild(textarea);

        if (!copied) {
          throw new Error("Não foi possível copiar a frase.");
        }
      }

      setCopyStatus("copied");
      window.setTimeout(() => {
        setCopyStatus("idle");
      }, 1500);
    } catch {
      setCopyStatus("error");
      window.setTimeout(() => {
        setCopyStatus("idle");
      }, 1500);
    }
  }

  function handleOpenGoogleTranslate() {
    const englishText = combinedSentence.trim();

    if (!englishText) {
      return;
    }

    const googleTranslateUrl = new URL("https://translate.google.com/");
    googleTranslateUrl.searchParams.set("hl", "pt-BR");
    googleTranslateUrl.searchParams.set("sl", language.split("-")[0]);
    googleTranslateUrl.searchParams.set("tl", "pt");
    googleTranslateUrl.searchParams.set("text", englishText);
    googleTranslateUrl.searchParams.set("op", "translate");

    window.open(
      googleTranslateUrl.toString(),
      "_blank",
      "noopener,noreferrer"
    );
  }

  function handleOpenEvaluationGoogleTranslate(text: string) {
    const englishText = text.trim();
    if (!englishText) return;

    const googleTranslateUrl = new URL("https://translate.google.com/");
    googleTranslateUrl.searchParams.set("hl", "pt-BR");
    googleTranslateUrl.searchParams.set("sl", language.split("-")[0]);
    googleTranslateUrl.searchParams.set("tl", "pt");
    googleTranslateUrl.searchParams.set("text", englishText);
    googleTranslateUrl.searchParams.set("op", "translate");

    window.open(googleTranslateUrl.toString(), "_blank", "noopener,noreferrer");
  }

  function handlePrintWorksheet() {
    // Imprime um documento isolado: evita páginas vazias causadas pelo layout do app.
    // O conteúdo já reflete o sorteio atual; nenhuma nova rodada é gerada.
    if (!hasEnoughVocabulary) return;

    const worksheet = document.querySelector<HTMLElement>(
      ".advanced-training-print-sheet"
    );
    const worksheetStyles = document.querySelector<HTMLStyleElement>(
      ".advanced-training > style"
    );
    if (!worksheet || !worksheetStyles) return;

    const printFrame = document.createElement("iframe");
    printFrame.setAttribute("title", "Impressão do treino avançado");
    printFrame.setAttribute("aria-hidden", "true");
    printFrame.style.position = "fixed";
    printFrame.style.width = "0";
    printFrame.style.height = "0";
    printFrame.style.border = "0";
    printFrame.style.opacity = "0";
    printFrame.style.pointerEvents = "none";

    printFrame.srcdoc = `<!doctype html>
<html lang="pt-BR">
<head>
  <meta charset="utf-8" />
  <title>Brazilian English Journey - Treino Avançado</title>
  <style>${worksheetStyles.textContent ?? ""}</style>
  <style>
    @media print {
      html, body { margin: 0 !important; padding: 0 !important; height: auto !important; min-height: 0 !important; overflow: visible !important; }
      .advanced-training-print-sheet { position: static !important; top: auto !important; left: auto !important; width: 100% !important; }
    }
  </style>
</head>
<body>${worksheet.outerHTML}</body>
</html>`;

    printFrame.onload = () => {
      const printWindow = printFrame.contentWindow;
      if (!printWindow) {
        printFrame.remove();
        return;
      }
      printWindow.addEventListener("afterprint", () => {
        window.setTimeout(() => printFrame.remove(), 500);
      }, { once: true });
      printWindow.focus();
      printWindow.print();
    };
    document.body.appendChild(printFrame);
  }

  async function handleEvaluate() {
    if (!isAuthorMode()) return;
    if (!hasEnoughVocabulary) {
      return;
    }

    if (
      !sentenceOne.trim() ||
      !sentenceTwo.trim() ||
      !combinedSentence.trim()
    ) {
      setEvaluationError(
        "Preencha as duas frases e a versão combinada antes de solicitar a avaliação."
      );
      return;
    }

    setEvaluating(true);
    setEvaluationError(null);
    setEvaluation(null);
    setEvaluationCopyStatus(null);

    try {
      const studentText = [
        `Frase 1: ${sentenceOne}`,
        `Frase 2: ${sentenceTwo}`,
        `Frase combinada: ${combinedSentence}`
      ].join("\n");

      const result = await evaluateTrainingWithAI({
        mode: "advanced",
        language,
        intention,
        studentText,
        vocabulary: {
          verbs: trainingItems.verbs.map((verb) => verb.base),
          adjectives: trainingItems.adjectives.map(
            (adjective) => adjective.adjective
          ),
          nouns: trainingItems.nouns.map((noun) => noun.noun),
          connectors: trainingItems.connectors.map(
            (connector) => connector.connector
          )
        }
      });

      setEvaluation(result);
    } catch (err) {
      setEvaluationError(
        err instanceof Error
          ? err.message
          : "Não foi possível avaliar o treino avançado."
      );
    } finally {
      setEvaluating(false);
    }
  }

  async function handleGoogleTranslate() {
    if (!isAuthorMode()) return;
    if (!combinedSentence.trim()) {
      setTranslationError(
        "Escreva a frase combinada antes de solicitar a tradução."
      );
      return;
    }

    setTranslating(true);
    setTranslationError(null);
    setGoogleTranslation(null);

    try {
      const result = await translateStudentLanguageToPortuguese(combinedSentence, language);
      setGoogleTranslation(result.translatedText);
    } catch (err) {
      setTranslationError(
        err instanceof Error
          ? err.message
          : "Não foi possível traduzir a frase com o Google."
      );
    } finally {
      setTranslating(false);
    }
  }

  function handleSpeakEnglish() {
    const englishText = combinedSentence.trim();

    if (!englishText) {
      setSpeechError(`Não há uma frase em ${languageName} para reproduzir.`);
      return;
    }

    if (!("speechSynthesis" in window)) {
      setSpeechError(
        "O recurso de voz não está disponível neste navegador."
      );
      return;
    }

    window.speechSynthesis.cancel();
    setSpeechError(null);
    setEvaluationSpeaking(null);

    const utterance = new SpeechSynthesisUtterance(englishText);
    const voices = window.speechSynthesis.getVoices();
    const americanVoice = voices.find(
      (voice) => voice.lang.toLowerCase() === language.toLowerCase()
    ) ?? voices.find(
      (voice) => voice.lang.toLowerCase().split("-")[0] === language.split("-")[0]
    );

    if (americanVoice) {
      utterance.voice = americanVoice;
    }

    utterance.lang = language;
    utterance.rate = 0.9;
    utterance.pitch = 1;

    utterance.onstart = () => {
      setSpeaking(true);
    };

    utterance.onend = () => {
      setSpeaking(false);
    };

    utterance.onerror = () => {
      setSpeaking(false);
      setSpeechError(`Não foi possível reproduzir a frase em ${languageName}.`);
    };

    window.speechSynthesis.speak(utterance);
  }

  async function handleCopyEvaluationSentence(
    text: string,
    target: "corrected" | "better"
  ) {
    const textToCopy = text.trim();
    if (!textToCopy) return;

    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(textToCopy);
      } else {
        // Compatibilidade com navegadores sem Clipboard API.
        const textarea = document.createElement("textarea");
        textarea.value = textToCopy;
        textarea.setAttribute("readonly", "");
        textarea.style.position = "fixed";
        textarea.style.opacity = "0";
        textarea.style.pointerEvents = "none";
        document.body.appendChild(textarea);
        try {
          textarea.select();
          if (!document.execCommand("copy")) {
            throw new Error("Falha ao copiar a frase.");
          }
        } finally {
          textarea.remove();
        }
      }
      setEvaluationCopyStatus({ target, status: "copied" });
    } catch {
      setEvaluationCopyStatus({ target, status: "error" });
    }
  }

  function handleSpeakEvaluationSentence(
    text: string,
    target: "corrected" | "better"
  ) {
    const englishText = text.trim();

    if (!englishText) {
      setSpeechError(`Não há uma frase em ${languageName} para reproduzir.`);
      return;
    }

    if (!("speechSynthesis" in window)) {
      setSpeechError(
        "O recurso de voz não está disponível neste navegador."
      );
      return;
    }

    window.speechSynthesis.cancel();
    setSpeechError(null);
    setSpeaking(false);
    setEvaluationSpeaking(null);

    const utterance = new SpeechSynthesisUtterance(englishText);
    const voices = window.speechSynthesis.getVoices();
    const americanVoice = voices.find(
      (voice) => voice.lang.toLowerCase() === language.toLowerCase()
    ) ?? voices.find(
      (voice) => voice.lang.toLowerCase().split("-")[0] === language.split("-")[0]
    );

    if (americanVoice) {
      utterance.voice = americanVoice;
    }

    utterance.lang = language;
    utterance.rate = 0.9;
    utterance.pitch = 1;

    utterance.onstart = () => {
      setSpeaking(false);
      setEvaluationSpeaking(target);
    };

    utterance.onend = () => {
      setEvaluationSpeaking(null);
    };

    utterance.onerror = () => {
      setEvaluationSpeaking(null);
      setSpeechError(`Não foi possível reproduzir a frase em ${languageName}.`);
    };

    window.speechSynthesis.speak(utterance);
  }

  return (
    <section className="advanced-training">
      <div className="training-toolbar">
        <button
          type="button"
          className="secondary-button"
          onClick={onBack}
        >
          Voltar para o Hashmap
        </button>

        {!loading && !error && (
          <button
            type="button"
            className="primary-button"
            onClick={generateNewRound}
          >
            Sortear novamente
          </button>
        )}
      </div>

      <div className="training-page-header">
        <p className="eyebrow">Treino avançado</p>
        <h1>{intention.intention}</h1>
        <p className="detail-english">{intention.targetIntention ?? intention.english}</p>

        {intention.examples && intention.examples.length > 0 && (
          <section className="training-intention-example">
            <h3>Exemplo</h3>
            <div className="example">
              <p>
                {renderHighlightedText(
                  intention.examples[0].pt,
                  intention.examples[0].ptIntent
                )}
              </p>
              <p className="english">
                {renderHighlightedText(
                  intention.examples[0].en,
                  intention.examples[0].enIntent
                )}
              </p>
            </div>
          </section>
        )}

        {intention.pattern && (
          <p className="training-pattern">{intention.pattern}</p>
        )}

        <p className="training-instruction">
          Crie duas frases independentes usando os elementos sorteados.
          Depois escolha um ou mais conectores para juntar as ideias
          em uma frase mais complexa.
        </p>
      </div>

      {loading && (
        <div className="status-card">
          <div className="spinner" />
