          <button
            type="button"
            aria-pressed={settings.order === "random"}
            onClick={() => updateSettings({ order: "random" })}
            style={{
              ...styles.segmentButton,
              ...(settings.order === "random"
                ? styles.segmentButtonSelected
                : {})
            }}
          >
