  function handleSpeakStory() {
    if (!story) {
      return;
    }

    const targetText = [
      story.title,
      ...story.paragraphs.map((paragraph) => paragraph.text)
    ]
      .filter(Boolean)
      .join(". ")
      .trim();

    if (!targetText) {
      setSpeechError(`Não há texto em ${languageName} para reproduzir.`);
      return;
    }

    if (!("speechSynthesis" in window)) {
      setSpeechError(
        "O recurso de voz não está disponível neste navegador."
      );
      return;
    }

    cancelSpeech();
    setSpeechError(null);
    setSpeakingParagraphIndex(null);

    const revision = speechRevision.current;
    const utterance = new SpeechSynthesisUtterance(targetText);
    const voices = window.speechSynthesis.getVoices();
    const targetVoice = voices.find(
      (voice) => voice.lang.toLowerCase() === language.toLowerCase()
    );

    if (targetVoice) {
      utterance.voice = targetVoice;
    }

    utterance.lang = language;
    utterance.rate = 0.9;
    utterance.pitch = 1;

    utterance.onstart = () => {
      if (revision !== speechRevision.current) return;
      setSpeaking(true);
    };

    utterance.onend = () => {
      if (revision !== speechRevision.current) return;
      setSpeaking(false);
      setSpeakingParagraphIndex(null);
    };

    utterance.onerror = () => {
      if (revision !== speechRevision.current) return;
      setSpeaking(false);
      setSpeakingParagraphIndex(null);
      setSpeechError(`Não foi possível reproduzir a história em ${languageName}.`);
    };

    window.speechSynthesis.speak(utterance);
  }

  async function handleCopyParagraph(text: string, index: number) {
    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(text);
      } else {
        const textarea = document.createElement("textarea");
        textarea.value = text;
        textarea.setAttribute("readonly", "");
        textarea.style.position = "fixed";
        textarea.style.left = "-9999px";
        document.body.appendChild(textarea);
        try {
          textarea.select();
          if (!document.execCommand("copy")) {
            throw new Error("Não foi possível copiar o parágrafo.");
          }
        } finally {
          textarea.remove();
        }
      }
      setCopyParagraphErrorIndex(null);
      setCopiedParagraphIndex(index);
    } catch (error) {
      console.error("[InterpretationPanel] Erro ao copiar parágrafo:", error);
      setCopiedParagraphIndex(null);
      setCopyParagraphErrorIndex(index);
    }
  }

