              cancelGeneration();
              setTheme(event.target.value);
              setStory(null);
              setStoryCopyFeedback("idle");
              setShowHqImage(false);
              setShowTarget(false);
              setError(null);
              setSpeechError(null);
              setSpeaking(false);
              setSpeakingParagraphIndex(null);

              if ("speechSynthesis" in window) {
                cancelSpeech();
              }
            }}
          >
            {THEMES.map((themeOption) => (
