                style={{
                  position: "fixed",
                  inset: 0,
                  width: "100vw",
                  height: "100dvh",
                  zIndex: 10000,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  padding: 0,
                  overflow: "hidden",
