                      event.ctrlKey ||
                      event.metaKey ||
                      event.shiftKey ||
                      hqZoom <= 1
                    ) {
                      return;
                    }

                    event.preventDefault();

                    const multiplier =
                      event.deltaMode === 1
                        ? 24
                        : event.deltaMode === 2
                          ? event.currentTarget.clientHeight
                          : 1;

                    event.currentTarget.scrollBy({
                      top: event.deltaY * multiplier,
                      behavior: "auto"
                    });
                  }}
                  style={{
                    position: "relative",
                    display: "flex",
                    alignItems: hqZoom > 1 ? "flex-start" : "center",
                    justifyContent: hqZoom > 1 ? "flex-start" : "center",
