                  type="button"
                  className="secondary-button"
                  onClick={handleCopyJson}
                >
                  {copyFeedback}
                </button>

                <button
                  type="button"
                  className="primary-button"
                  onClick={handleDownloadJson}
                >
                  Baixar JSON
                </button>
              </div>
              </div>
            </div>
          )}

          {story.source === "local" && (
            <div
              role="status"
              style={{
                display: "flex",
                alignItems: "flex-start",
                gap: "0.75rem",
                marginTop: "1.5rem",
                padding: "0.9rem 1rem",
                border: "1px solid rgba(202, 138, 4, 0.28)",
                borderRadius: "12px",
                background: "rgba(254, 240, 138, 0.28)",
                color: "inherit"
              }}
            >
              <span aria-hidden="true">🟡</span>

              <div>
                <strong>História da biblioteca local</strong>
                <p style={{ margin: "0.25rem 0 0" }}>
                  Esta história foi carregada da biblioteca de histórias do
                  Mental Hashmap.
                </p>
              </div>
            </div>
          )}

          <div className="interpretation-used">
            <h3>Intenções utilizadas</h3>

            <div className="interpretation-used-list">
              {story.intentionsUsed.map((id) => {
                const intention = intentions.find(
                  (item) => item.id === id
                );

                return intention ? (
                  <button
                    type="button"
                    className="pill interpretation-used-button"
                    key={id}
                    onClick={() => onSelectIntention(intention)}
                    title={`Ver detalhes de ${intention.intention}`}
                  >
                    {intention.intention}
                  </button>
                ) : (
                  <span
                    className="pill"
                    key={id}
                  >
                    {story.paragraphs.flatMap(paragraph => paragraph.intentions).find(item => item.intentionId === id)?.ptIntent ?? "Intenção não disponível neste catálogo"}
                  </span>
                );
              })}
            </div>
          </div>
        </article>
      )}
    </section>
  );
}

src/hooks/useStoryShadowing.ts:
import { useEffect, useRef, useState } from "react";
import type { StudentLanguage } from "../config/languages";
import { getParagraphText, type LocalStory } from "../services/localStoryService";
import { WalkingAudio } from "../utils/walkingAudio";
import { practiceSteps, responsePause, sentenceSegments, type ShadowingSettings } from "../utils/storyShadowing";

const repeatPrompts: Record<StudentLanguage, string> = {
  "pt-BR": "Repita depois de mim", "en-US": "Repeat after me", "fr-FR": "Répétez après moi", "es-ES": "Repite después de mí"
};
export function useStoryShadowing(story: LocalStory, language: StudentLanguage, settings: ShadowingSettings, selected: number) {
  const audio = useRef(new WalkingAudio());
  const [playing, setPlaying] = useState(false);
  const [paragraph, setParagraph] = useState(selected);
  const [sentence, setSentence] = useState(0);
  const [step, setStep] = useState(0);
  const [phase, setPhase] = useState<"prompt" | "speech" | "wait" | "ready">("prompt");
  const [complete, setComplete] = useState(false);
  const [completed, setCompleted] = useState<Set<number>>(new Set());
  const [error, setError] = useState("");
  const [voices, setVoices] = useState<SpeechSynthesisVoice[]>([]);
  const [elapsed, setElapsed] = useState(0);
  const [warning, setWarning] = useState("");
  const [revision, setRevision] = useState(0);
  const clock = useRef({ accumulated: 0, since: null as number | null });
  const delay = useRef({ remaining: 0, since: null as number | null });
  const [fullReading, setFullReading] = useState(false);
  const readingReturn = useRef(false);
  const steps = practiceSteps(settings);
  const current = steps[step] ?? steps[0];
  const text = getParagraphText(story.paragraphs[paragraph], language);
  const segments = settings.unit === "sentence" ? sentenceSegments(text, language) : [text];
  const spokenText = fullReading ? text : segments[sentence] ?? text;
  const hasVoice = voices.some(v => v.lang.toLowerCase().split("-")[0] === language.slice(0, 2));

  useEffect(() => {
    const synth = window.speechSynthesis;
    if (!synth) return;
    const update = () => setVoices(synth.getVoices());
    update(); synth.addEventListener("voiceschanged", update);
    return () => synth.removeEventListener("voiceschanged", update);
  }, []);

  function stopAudio() {
    audio.current.cancel();
    if (delay.current.since !== null) {
      delay.current.remaining = Math.max(0, delay.current.remaining - (performance.now() - delay.current.since));
      delay.current.since = null;
    }
  }
  function pause() { stopAudio(); setPlaying(false); }
  function resetUnit() {
    stopAudio(); delay.current = { remaining: 0, since: null };
    setStep(0); setPhase("prompt"); setComplete(false); setFullReading(false); setError(""); setRevision(v => v + 1);
  }
  function navigate(direction: number) {
    resetUnit();
    const nextSentence = sentence + direction;
    if (nextSentence >= 0 && nextSentence < segments.length) setSentence(nextSentence);
    else if (settings.scope === "story") {
      const next = Math.max(0, Math.min(story.paragraphs.length - 1, paragraph + direction));
      setParagraph(next);
      setSentence(direction < 0 && settings.unit === "sentence" ? sentenceSegments(getParagraphText(story.paragraphs[next], language), language).length - 1 : 0);
    }
  }
  function play() {
    if (!hasVoice) { setError("Nenhuma voz compatível disponível. Habilite uma voz deste idioma no navegador ou sistema e tente novamente. O texto permanece disponível para leitura."); return; }
    if (complete) return;
    if (phase === "ready") {
      if (step + 1 < steps.length) setStep(step + 1);
      setPhase("prompt");
    }
    setError(""); setPlaying(true);
  }
  function finishUnit() {
    if (!fullReading && sentence + 1 < segments.length) {
      setSentence(v => v + 1); setStep(0); setPhase("prompt");
      if (settings.control === "manual") setPlaying(false);
      return;
    }
    setCompleted(previous => new Set(previous).add(paragraph));
    if (settings.scope === "story" && paragraph + 1 < story.paragraphs.length) {
      if (settings.control === "automatic" && settings.automatic) {
        setParagraph(v => v + 1); setSentence(0); setStep(0); setPhase("prompt"); setFullReading(false);
      } else { setPhase("ready"); setPlaying(false); }
    } else { setComplete(true); setPlaying(false); }
  }

  useEffect(() => {
    if (!playing || complete) return;
    const fail = () => { setError("Não foi possível reproduzir a voz. Verifique as vozes instaladas e toque em Play para tentar novamente."); setPlaying(false); };
    if (phase === "ready") { setPlaying(false); return; }
    if (phase === "prompt") {
      if (current.technique === "repeat" && !fullReading) {
        audio.current.play(repeatPrompts[language], language, settings.rate, 0, () => {}, () => setPhase("speech"), fail, true);
      } else setPhase("speech");
    } else if (phase === "speech") {
      audio.current.play(spokenText, language, settings.rate, 0, () => {}, () => {
        delay.current = { remaining: (current.technique === "repeat" && !fullReading ? responsePause(spokenText, settings.rate) : 0) + settings.interval * 1000, since: null };
        setPhase("wait");
      }, fail, true);
    } else {
      delay.current.since = performance.now();
      audio.current.wait(delay.current.remaining, () => {
        delay.current = { remaining: 0, since: null };
        if (fullReading) { setFullReading(false); setPlaying(false); setComplete(readingReturn.current); setPhase("ready"); return; }
        if (step + 1 < steps.length) {
          if (settings.control === "manual" && settings.technique !== "combined") { setPhase("ready"); setPlaying(false); }
          else { setStep(v => v + 1); setPhase("prompt"); }
        } else finishUnit();
      });
    }
    return stopAudio;
  }, [playing, complete, phase, paragraph, sentence, step, revision, fullReading, language, settings]);

  useEffect(() => {
    const now = performance.now();
    if (playing && clock.current.since === null) clock.current.since = now;
    if (!playing && clock.current.since !== null) {
      clock.current.accumulated += now - clock.current.since; clock.current.since = null;
    }
    const update = () => setElapsed(clock.current.accumulated + (clock.current.since === null ? 0 : performance.now() - clock.current.since));
    update();
    if (!playing) return;
    const timer = setInterval(update, 250);
    return () => clearInterval(timer);
  }, [playing]);

  useEffect(() => {
    let disposed = false;
    let lock: WakeLockSentinel | null = null;
    let requesting = false;
    async function acquire() {
      if (disposed || requesting || lock || !playing || !settings.keepAwake || document.visibilityState !== "visible") return;
      if (!("wakeLock" in navigator)) { setWarning("Este navegador não permite manter a tela ativa."); return; }
      requesting = true;
      try {
        const acquired = await navigator.wakeLock.request("screen");
        if (disposed) { await acquired.release(); return; }
        lock = acquired; setWarning("");
        acquired.addEventListener("release", () => {
          if (lock === acquired) lock = null;
          if (!disposed) setWarning("O bloqueio de tela foi liberado. Mantenha a página visível para continuar.");
        });
      } catch { if (!disposed) setWarning("Não foi possível manter a tela ativa."); }
      finally { requesting = false; }
    }
    void acquire(); document.addEventListener("visibilitychange", acquire);
    return () => { disposed = true; document.removeEventListener("visibilitychange", acquire); void lock?.release().catch(() => {}); };
  }, [playing, settings.keepAwake]);
  useEffect(() => () => audio.current.cancel(), []);

  return { playing, paragraph, sentence, segments, step: current, phase, complete,
    completed: settings.scope === "paragraph" ? Number(completed.has(paragraph)) : completed.size,
    elapsed, error, warning, hasVoice, fullReading,
    canPrevious: sentence > 0 || (settings.scope === "story" && paragraph > 0),
    canNext: sentence + 1 < segments.length || (settings.scope === "story" && paragraph + 1 < story.paragraphs.length),
    play, pause, navigate,
    repeat() { resetUnit(); if (hasVoice) setPlaying(true); },
    stop() { pause(); resetUnit(); },
    configure(next?: ShadowingSettings) {
      pause(); resetUnit(); setSentence(0);
      if (next && next.scope !== settings.scope) {
        setCompleted(new Set());
        if (next.scope === "story") setParagraph(0);
      }
    },
    readParagraph() { readingReturn.current = complete; resetUnit(); setFullReading(true); setPhase("speech"); if (hasVoice) setPlaying(true); }
  };
}

src/services/aiEvaluationService.ts:
import { isAuthorMode } from "../utils/authorMode";
import type { MentalIntention } from "../types/hashmap";
import { LANGUAGES, type SourceLanguage, type StudentLanguage } from "../config/languages";

export type TrainingEvaluationMode = "basic" | "advanced";

export interface TrainingVocabulary {
  verbs?: string[];
  adjectives?: string[];
  nouns?: string[];
  connectors?: string[];
}

export interface AIEvaluationRequest {
  mode: TrainingEvaluationMode;
  language?: StudentLanguage;
  sourceLanguage?: SourceLanguage;
  intention: MentalIntention;
  studentText: string;
  vocabulary?: TrainingVocabulary;
}

export interface AIEvaluationResult {
  score: number;
  grammar: "excellent" | "good" | "needs_improvement";
  naturalness: "excellent" | "good" | "needs_improvement";
  intentionUsedCorrectly: boolean;
  vocabularyUsedCorrectly: boolean;
  feedbackPt: string;
  correctedSentence: string;
  betterVersion: string;
}

interface GeminiResponse {
  candidates?: Array<{
    content?: {
      parts?: Array<{
        text?: string;
      }>;
    };
    finishReason?: string;
  }>;
  promptFeedback?: {
    blockReason?: string;
  };
  error?: {
    code?: number;
    message?: string;
    status?: string;
  };
}

const GEMINI_API_KEY = (
  import.meta.env.VITE_GEMINI_API_KEY as string | undefined
)?.trim();

const GEMINI_MODEL =
  (
    import.meta.env.VITE_GEMINI_MODEL as string | undefined
  )?.trim() || "gemini-3.8-flash";

const GEMINI_ENDPOINT =
  `https://generativelanguage.googleapis.com/v1beta/models/` +
  `${encodeURIComponent(GEMINI_MODEL)}:generateContent`;

const evaluationSchema = {
  type: "OBJECT",
  properties: {
    score: {
      type: "INTEGER",
      description: "Score from 0 to 10."
    },
    grammar: {
      type: "STRING",
      enum: ["excellent", "good", "needs_improvement"]
    },
    naturalness: {
      type: "STRING",
      enum: ["excellent", "good", "needs_improvement"]
    },
    intentionUsedCorrectly: {
      type: "BOOLEAN"
    },
    vocabularyUsedCorrectly: {
      type: "BOOLEAN"
    },
    feedbackPt: {
      type: "STRING",
      description:
        "Short, constructive feedback in Brazilian Portuguese."
    },
    correctedSentence: {
      type: "STRING",
      description:
        "Corrected version that preserves the student's intended meaning."
    },
    betterVersion: {
      type: "STRING",
      description:
        "A natural version of the student's answer in the requested target language."
    }
  },
  required: [
    "score",
    "grammar",
    "naturalness",
    "intentionUsedCorrectly",
    "vocabularyUsedCorrectly",
    "feedbackPt",
    "correctedSentence",
    "betterVersion"
  ]
};

function formatList(values?: string[]): string {
  if (!values || values.length === 0) {
    return "nenhum item obrigatório";
  }

  return values.join(", ");
}

function buildPrompt(request: AIEvaluationRequest): string {
  const {
    mode,
    intention,
    language = "en-US",
    sourceLanguage = "pt-BR",
    studentText,
    vocabulary
  } = request;

  const basicInstructions = `
O aluno está fazendo um TREINO BÁSICO.
Avalie se ele conseguiu criar uma frase coerente usando a intenção mental
e, quando possível, os elementos sorteados.
`;

  const advancedInstructions = `
O aluno está fazendo um TREINO AVANÇADO.
A resposta pode conter duas frases independentes e uma versão final unindo
as ideias com um ou mais conectores.
Avalie também se a relação lógica criada pelos conectores faz sentido.
`;

  return `
Você é um avaliador de ${LANGUAGES[language].name.toLowerCase()} para um aluno que usa ${LANGUAGES[sourceLanguage].name.toLowerCase()} como idioma de origem.

Seu objetivo é avaliar a produção do aluno de forma prática, clara,
encorajadora e rigorosa, sem ser excessivamente acadêmico.

${mode === "basic" ? basicInstructions : advancedInstructions}

INTENÇÃO MENTAL:
Idioma de origem (${sourceLanguage}): ${intention.intention}
Idioma estudado (${language}): ${intention.english}
Pattern: ${intention.pattern ?? "não informado"}

VOCABULÁRIO SORTEADO:
Verbos: ${formatList(vocabulary?.verbs)}
Adjetivos: ${formatList(vocabulary?.adjectives)}
Nouns: ${formatList(vocabulary?.nouns)}
Conectores: ${formatList(vocabulary?.connectors)}

RESPOSTA DO ALUNO:
${studentText}

CRITÉRIOS:
1. Gramática.
2. Naturalidade no idioma estudado (${language}).
3. Uso correto da intenção mental.
4. Uso coerente do vocabulário sorteado.
5. No treino avançado, coerência entre as ideias e os conectores.
6. Não penalize o aluno apenas por não usar todos os itens sorteados
   quando a frase continuar natural e cumprir o objetivo comunicativo.
7. Preserve o sentido pretendido pelo aluno ao corrigir.
8. O feedback deve ser curto e em português do Brasil (idioma da interface).
9. correctedSentence deve corrigir a resposta com o mínimo de alterações.
10. betterVersion deve mostrar uma forma mais natural de dizer a mesma ideia no idioma estudado.
11. correctedSentence e betterVersion devem estar exclusivamente no idioma estudado (${language}).

Dê uma nota inteira de 0 a 10.
Responda exclusivamente no formato JSON solicitado.
`.trim();
}

function normalizeResult(
  value: AIEvaluationResult
): AIEvaluationResult {
  return {
    ...value,
    score: Math.max(0, Math.min(10, Math.round(value.score)))
  };
}

export async function evaluateTrainingWithAI(
  request: AIEvaluationRequest
): Promise<AIEvaluationResult> {
  if (!isAuthorMode()) throw new Error("Recurso exclusivo do Modo Autor.");
  if (!GEMINI_API_KEY) {
    throw new Error(
      "VITE_GEMINI_API_KEY não foi configurada no arquivo .env."
    );
  }

  if (!request.studentText.trim()) {
    throw new Error(
      "Escreva uma frase antes de solicitar a avaliação."
    );
  }

  const response = await fetch(
    GEMINI_ENDPOINT,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-goog-api-key": GEMINI_API_KEY
      },
      body: JSON.stringify({
        contents: [
          {
            role: "user",
            parts: [
              {
                text: buildPrompt(request)
              }
            ]
          }
        ],
        generationConfig: {
          responseMimeType: "application/json",
          responseSchema: evaluationSchema,
          temperature: 0.2
        }
      })
    }
  );

  const data = (await response.json()) as GeminiResponse;

  if (!response.ok || data.error) {
    throw new Error(
      data.error?.message ||
        `Erro ao acessar a IA (${response.status}).`
    );
  }

  if (data.promptFeedback?.blockReason) {
    throw new Error(
      `A avaliação foi bloqueada pela IA: ` +
        `${data.promptFeedback.blockReason}.`
    );
  }

  const responseText = data.candidates
    ?.flatMap((candidate) => candidate.content?.parts ?? [])
    .map((part) => part.text ?? "")
    .join("")
    .trim();

  if (!responseText) {
    throw new Error(
      "A IA não retornou uma avaliação válida."
    );
  }

  try {
    const parsed = JSON.parse(responseText) as AIEvaluationResult;
    return normalizeResult(parsed);
  } catch {
    throw new Error(
      "A IA retornou uma resposta em formato inesperado."
    );
  }
}

